import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import * as TooltipPrimitive from "@radix-ui/react-tooltip";
import { cn } from "@/lib/utils";

export type TooltipVariant = "default" | "rich" | "shortcut" | "interactive";

export interface TooltipProviderProps
  extends React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Provider> {}

export function TooltipProvider({
  delayDuration = 400,
  skipDelayDuration = 280,
  ...props
}: TooltipProviderProps) {
  return (
    <TooltipPrimitive.Provider
      delayDuration={delayDuration}
      skipDelayDuration={skipDelayDuration}
      {...props}
    />
  );
}

export const Tooltip = TooltipPrimitive.Root;
export const TooltipTrigger = TooltipPrimitive.Trigger;

export interface TooltipContentProps
  extends Omit<
    React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Content>,
    "title"
  > {
  variant?: TooltipVariant;
  /** Rich tooltip heading — separate from the native `title` attribute. */
  heading?: React.ReactNode;
  shortcut?: string[];
  /** When true, pointer can enter the tooltip (for links/buttons inside). */
  interactive?: boolean;
  /** Follow cursor — positions content near pointer instead of trigger center. */
  followCursor?: boolean;
}

export function TooltipContent({
  className,
  variant = "default",
  heading,
  shortcut,
  interactive = false,
  followCursor = false,
  sideOffset = 6,
  children,
  ...props
}: TooltipContentProps) {
  const [pointer, setPointer] = React.useState<{ x: number; y: number } | null>(null);

  React.useEffect(() => {
    if (!followCursor) return;

    const handleMove = (event: PointerEvent) => {
      setPointer({ x: event.clientX, y: event.clientY });
    };

    window.addEventListener("pointermove", handleMove, { passive: true });
    return () => window.removeEventListener("pointermove", handleMove);
  }, [followCursor]);

  const followStyle =
    followCursor && pointer
      ? {
          position: "fixed" as const,
          left: pointer.x + 14,
          top: pointer.y + 14,
          transform: "none",
        }
      : undefined;

  const isRich = variant === "rich" || Boolean(heading);
  const isShortcut = variant === "shortcut" || Boolean(shortcut?.length);
  const isInteractive = variant === "interactive" || interactive;

  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-wensity-tooltip-content
        sideOffset={followCursor ? 0 : sideOffset}
        className={cn(
          "z-[130] max-w-[16rem] rounded-xl border border-[#ded3c5] bg-[#f7f2e9] px-2.5 py-1.5",
          "text-[12px] leading-[1.45] text-[#181716]",
          "[box-shadow:0_20px_52px_-28px_rgba(0,0,0,.78),0_8px_24px_-16px_rgba(18,16,13,.42),0_1px_2px_rgba(18,16,13,.10)]",
          "origin-[var(--radix-tooltip-content-transform-origin)] transform-gpu outline-none",
          "data-[state=delayed-open]:animate-in data-[state=delayed-open]:fade-in-0 data-[state=delayed-open]:zoom-in-95",
          "data-[state=delayed-open]:data-[side=bottom]:slide-in-from-top-1 data-[state=delayed-open]:data-[side=top]:slide-in-from-bottom-1",
          "data-[state=delayed-open]:data-[side=left]:slide-in-from-right-1 data-[state=delayed-open]:data-[side=right]:slide-in-from-left-1",
          "data-[state=instant-open]:animate-none data-[state=instant-open]:opacity-100",
          "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
          "data-[state=delayed-open]:duration-150 data-[state=closed]:duration-100",
          "data-[state=delayed-open]:ease-[cubic-bezier(0.23,1,0.32,1)] data-[state=closed]:ease-[cubic-bezier(0.23,1,0.32,1)]",
          "motion-reduce:animate-none",
          isRich && "max-w-[18rem] px-3 py-2.5",
          isInteractive && "pointer-events-auto",
          className,
        )}
        style={followStyle}
        onPointerDownOutside={(event) => {
          if (isInteractive) event.preventDefault();
        }}
        {...props}
      >
        {isRich && heading ? (
          <div className="space-y-1">
            <p className="text-[12px] font-semibold text-[#181716]">{heading}</p>
            {children ? (
              <p className="text-[11px] leading-[1.45] text-[#655d52]">
                {children}
              </p>
            ) : null}
          </div>
        ) : (
          children
        )}

        {isShortcut && shortcut?.length ? (
          <span className="ml-2 inline-flex items-center gap-0.5 align-middle">
            {shortcut.map((key) => (
              <kbd
                key={key}
                className={cn(
                  "inline-flex h-[18px] min-w-[18px] items-center justify-center rounded border border-[#d6cab9]",
                  "bg-[#ede5da] px-1",
                  "font-mono text-[10px] font-medium text-[#5f574c]",
                )}
              >
                {key}
              </kbd>
            ))}
          </span>
        ) : null}

        {!followCursor ? (
          <TooltipPrimitive.Arrow
            className="fill-[#f7f2e9]"
            width={10}
            height={5}
          />
        ) : null}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

/** Convenience wrapper for rich two-line tooltips. */
export function TooltipRich({
  title,
  description,
  children,
  open,
  defaultOpen,
  onOpenChange,
  delayDuration,
}: {
  title: React.ReactNode;
  description: React.ReactNode;
  children: React.ReactElement;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  delayDuration?: number;
}) {
  return (
    <Tooltip
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      delayDuration={delayDuration}
    >
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent variant="rich" heading={title}>
        {description}
      </TooltipContent>
    </Tooltip>
  );
}

/** Convenience wrapper for shortcut hints. */
export function TooltipShortcut({
  label,
  shortcut,
  children,
  open,
  defaultOpen,
  onOpenChange,
  delayDuration,
}: {
  label: React.ReactNode;
  shortcut: string[];
  children: React.ReactElement;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  delayDuration?: number;
}) {
  return (
    <Tooltip
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      delayDuration={delayDuration}
    >
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent variant="shortcut" shortcut={shortcut}>
        {label}
      </TooltipContent>
    </Tooltip>
  );
}
